// ===== IP12 weekly WP diff → git-commit-style changelog =====
const norm = v => String(v ?? '').trim();
const tasks = $('Read Tasks').all().map(i => i.json).filter(r => norm(r.ID));
const snap  = $('Read Snapshot').all().map(i => i.json).filter(r => norm(r.ID));
let commits = [];
try { commits = $('GitHub Commits').all().map(i => i.json).filter(c => c && c.sha); } catch (e) {}

const now  = $now.setZone('Europe/Berlin');
const week = now.weekNumber;
const date = now.toFormat('yyyy-MM-dd');
const prev = Object.fromEntries(snap.map(r => [norm(r.ID), r]));
const isFirstRun = snap.length === 0;

const changes = [];
const add = (type, t, msg) => changes.push({ type, id: norm(t.ID), owner: norm(t.Owner), msg });
const seen = new Set();

for (const t of tasks) {
  const id = norm(t.ID);
  seen.add(id);
  const p = prev[id];
  if (!p || norm(p.Status) === 'Removed') {
    add('feat', t, `add "${norm(t.Task)}"${norm(t.Owner) ? ` [${norm(t.Owner)}]` : ''}`);
    continue;
  }
  const ps = norm(p.Status), ns = norm(t.Status);
  if (ps !== ns) {
    const done = /^(done|completed|finished|erledigt)$/i.test(ns);
    add(done ? 'done' : 'progress', t, done ? `complete "${norm(t.Task)}" (${ps || '—'} → ${ns})` : `${ps || '—'} → ${ns}`);
  }
  if (norm(p.Owner) !== norm(t.Owner)) add('reassign', t, `owner ${norm(p.Owner) || '—'} → ${norm(t.Owner) || '—'}`);
  for (const f of ['Task', 'Deliverable', 'Dependency']) {
    if (norm(p[f]) !== norm(t[f])) add('refactor', t, `${f.toLowerCase()}: "${norm(p[f]) || '—'}" → "${norm(t[f]) || '—'}"`);
  }
  if (norm(p.Note) !== norm(t.Note) && norm(t.Note)) add('docs', t, `note: ${norm(t.Note)}`);
}
for (const [id, p] of Object.entries(prev)) {
  if (!seen.has(id) && norm(p.Status) !== 'Removed') add('remove', p, `drop "${norm(p.Task)}"`);
}

// short "commit hash"
let h = 0;
for (const ch of JSON.stringify(changes) + date) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
const hash = h.toString(16).padStart(8, '0').slice(0, 7);

// stats like "3 files changed"
const count = {};
for (const c of changes) count[c.type] = (count[c.type] || 0) + 1;
const statLine = changes.length
  ? `${changes.length} change(s): ` + Object.entries(count).map(([k, v]) => `${v} ${k}`).join(', ')
  : 'no task changes this week';
const statusCount = {};
for (const t of tasks) { const s = norm(t.Status) || 'No status'; statusCount[s] = (statusCount[s] || 0) + 1; }
const statusLine = Object.entries(statusCount).map(([k, v]) => `${k} ${v}`).join(' · ');

const title = isFirstRun ? 'Initial commit: WP baseline' : `Weekly WP update (KW ${week})`;
const order = ['feat', 'done', 'progress', 'reassign', 'refactor', 'docs', 'remove'];
const sorted = [...changes].sort((a, b) => order.indexOf(a.type) - order.indexOf(b.type) || a.id.localeCompare(b.id, undefined, { numeric: true }));

let report = `commit ${hash}  (KW ${week})\nAuthor: IP12 WP Bot\nDate:   ${now.toFormat('ccc dd LLL yyyy HH:mm')}\n\n    ${title}\n\n`;
report += sorted.length ? sorted.map(c => `    ${c.type}(${c.id}): ${c.msg}`).join('\n') : '    chore: no task changes this week';
report += `\n\n ${statLine}\n Board: ${statusLine}\n`;

if (commits.length) {
  const authors = new Set(commits.map(c => c.commit?.author?.name || c.author?.login || '?'));
  report += `\n GitHub: ${commits.length} commit(s) by ${authors.size} author(s)\n`;
  report += commits.slice(0, 30).map(c =>
    `    ${c.sha.slice(0, 7)} ${(c.commit?.author?.name || c.author?.login || '?')}: ${(c.commit?.message || '').split('\n')[0]}`
  ).join('\n') + '\n';
} else {
  report += `\n GitHub: no commits this week (or repo not connected)\n`;
}

const changelogRows = (sorted.length ? sorted : [{ type: 'chore', id: '-', owner: '', msg: 'no task changes this week' }])
  .map(c => ({ Week: `KW ${week}`, Date: date, Hash: hash, Type: c.type, ID: c.id, Message: c.msg, Owner: c.owner }));

const cols = ['WP', 'ID', 'Task', 'Owner', 'Deliverable', 'Dependency', 'Status', 'Note'];
const pick = r => Object.fromEntries(cols.map(k => [k, norm(r[k])]));
const snapshotRows = tasks.map(pick);
for (const [id, p] of Object.entries(prev)) if (!seen.has(id)) snapshotRows.push({ ...pick(p), Status: 'Removed' });

return [{ json: { week, date, hash, subject: `[IP12] ${title} – ${hash}`, report, changelogRows, snapshotRows } }];
